    double angle, c, rr, mg;
    if (current == NULL || target == NULL || required_rate == NULL || margin == NULL)
        return ADCS_E_NULL;
    if (!isfinite(duration) || duration <= 0.0 ||
        !isfinite(max_rate) || max_rate < 0.0 ||
        !isfinite(current->w) || !isfinite(current->x) ||
        !isfinite(current->y) || !isfinite(current->z) ||
        !isfinite(target->w) || !isfinite(target->x) ||
        !isfinite(target->y) || !isfinite(target->z)) {
        *required_rate = INFINITY;
        *margin = -INFINITY;
        return ADCS_E_RANGE;
    }
    if (adcs_quat_normalize(current, &qc) != ADCS_OK ||
        adcs_quat_normalize(target, &qt) != ADCS_OK) {
        *required_rate = INFINITY;
        *margin = -INFINITY;
        return ADCS_E_RANGE;
    }
    qrel = adcs_quat_multiply(&qt, &adcs_quat_conjugate(&qc));
    c = fabs(qrel.w);
    c = ADCS_CLAMP(c, 0.0, 1.0);
    angle = 2.0 * acos(c);
    rr = angle / duration;
    mg = max_rate - rr;
    *required_rate = rr;
    *margin = mg;
    return ADCS_OK;
}

