candidates.raw:
    adcs_quat_t q_cur, q_tgt, q_conj, q_rel;
    double w_abs, angle;

    if (required_rate == NULL || margin == NULL) {
        return ADCS_E_NULL;
    }
    *required_rate = INFINITY;
    *margin = -INFINITY;

    if (current == NULL || target == NULL) {
        return ADCS_E_NULL;
    }

    if (!isfinite(duration) || duration <= 0.0) {
        return ADCS_E_RANGE;
    }
    if (!isfinite(max_rate)) {
        return ADCS_E_RANGE;
    }
    if (!isfinite(current->w) || !isfinite(current->x) || !isfinite(current->y) ||
        !isfinite(current->z)) {
        return ADCS_E_RANGE;
    }
    if (!isfinite(target->w) || !isfinite(target->x) || !isfinite(target->y) ||
        !isfinite(target->z)) {
        return ADCS_E_RANGE;
    }

    if (adcs_quat_normalize(current, &q_cur) != ADCS_OK) {
        return ADCS_E_RANGE;
    }
    if (adcs_quat_normalize(target, &q_tgt) != ADCS_OK) {
        return ADCS_E_RANGE;
    }

    q_conj = adcs_quat_conjugate(&q_cur);
    q_rel = adcs_quat_multiply(&q_tgt, &q_conj);

    w_abs = fabs(q_rel.w);
    if (w_abs > 1.0) {
        w_abs = 1.0;
    }
    if (w_abs < 0.0) {
        w_abs = 0.0;
    }
    angle = 2.0 * acos(w_abs);

    *required_rate = angle / duration;
    *margin = max_rate - *required_rate;

    return ADCS_OK;
}

